from pathlib import Path
import zipfile, re, html
from xml.etree import ElementTree as ET
root=Path('documents')
patterns=[r'funds\s*(?:&|and)\s*asset\s*management', r'lp\s*advisory\s*committee', r'limited\s*partner\s*advisory\s*committee', r'\bLPAC\b', r'\bLPA\b', r'advisory\s+committee']
rx=[re.compile(p,re.I) for p in patterns]

def text_file(p):
    if p.suffix.lower() in {'.docx','.pptx','.xlsx'}:
        try:
            with zipfile.ZipFile(p) as z:
                chunks=[]
                for n in z.namelist():
                    if n.endswith('.xml'):
                        try:
                            data=z.read(n)
                            txt=' '.join(ET.fromstring(data).itertext())
                            chunks.append(txt)
                        except Exception:
                            pass
                return ' '.join(chunks)
        except Exception:
            return ''
    if p.suffix.lower() in {'.eml','.txt','.md','.csv'}:
        try:return p.read_text(errors='ignore')
        except:return ''
    return ''

out=[]
for p in root.rglob('*'):
    if not p.is_file(): continue
    t=text_file(p)
    if not t: continue
    hits=[]
    for r in rx:
        for m in r.finditer(t):
            a=max(0,m.start()-180); b=min(len(t),m.end()+300)
            s=re.sub(r'\s+',' ',t[a:b])
            hits.append(s)
    if hits:
        # de-dupe exact snippets
        dd=[]
        for h in hits:
            if h not in dd: dd.append(h)
        out.append(f'FILE: {p}')
        for h in dd[:12]: out.append(f'  {h}')
        out.append('')
Path('search_results.txt').write_text('\n'.join(out))
print(f'Wrote {len(out)} lines for {sum(1 for x in out if x.startswith("FILE:") )} files')
