        names=[n for n in z.namelist() if n.endswith('.xml') and '/word/' in n and not any(x in n for x in ('styles','settings','theme','fontTable'))]
        t=' '.join(' '.join(ET.fromstring(z.read(n)).itertext()) for n in names)
    except: continue
    if re.search(r'Private Funds|LPAC|Limited Partner Advisory Committee|LP Advisory Committee',t,re.I):
      mid=p.parts[2]
      hits=[]
      for pat in [r'Private Funds',r'LPAC',r'Limited Partner Advisory Committee',r'LP Advisory Committee']:
        mm=re.search(pat,t,re.I)
        if mm:
          hits.append(re.sub(r'\s+',' ',t[max(0,mm.start()-80):mm.end()+160]))
      m.setdefault(mid,[]).append((str(p),hits))
with open('private_funds_lpac_scan.txt','w') as f:
  for mid,items in m.items():
    f.write('MATTER '+mid+'\n')
    for p,h in items[:8]:
      f.write('  '+p+'\n')
      for x in h[:4]:f.write('    '+x+'\n')
print('matter count',len(m),'ids',list(m))
